SELECT s.id, s.name, s.department, s.position, s.phone, s.work_status AS workStatus, COUNT(r.id) AS recordCount, ROUND(AVG(r.repair_hours), 2) AS avgRepairHours FROM maintenance_staff s LEFT JOIN maintenance_record r ON s.id = r.staff_id AND r.deleted = 0
s.deleted = 0
AND s.department = #{department}
AND s.work_status = #{workStatus}
GROUP BY s.id, s.name, s.department, s.position, s.phone, s.work_status ORDER BY recordCount ASC

SELECT * FROM maintenance_staff

    deleted = 0

        AND name LIKE CONCAT('%', #{name}, '%')


        AND department = #{department}


        AND position LIKE CONCAT('%', #{position}, '%')


        AND work_status = #{workStatus}


ORDER BY ${sortField} ${sortOrder} LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM maintenance_staff

    deleted = 0

        AND name LIKE CONCAT('%', #{name}, '%')


        AND department = #{department}


        AND position LIKE CONCAT('%', #{position}, '%')


        AND work_status = #{workStatus}
